headers:
three_not_square_quadInt {tau nu : ℤ}
    (hpos : 0 < discriminant tau nu) :
    ¬ ∃ r : QuadInt tau nu, r*r = 3

noSmallQuadruple_normalized {tau nu : ℤ}
    (htau : tau = 0 ∨ tau = 1)
    (hpos : 0 < discriminant tau nu) : NoSmallQuadruple tau nu

small_negative_radicand_not_square {tau nu m : ℤ}
    (hlarge : 32 < discriminant tau nu) (hm : m = -1 ∨ m = -3) :
    ¬ ∃ r : QuadInt tau nu, r*r = (m : QuadInt tau nu)

product_neg_one_norms {tau nu : ℤ}
    (hd : 0 < discriminant tau nu) (a b : QuadInt tau nu)
    (hprod : a*b+1=0) : a.norm=1 ∧ b.norm=1
